<script setup lang="ts">
import { computed, ref } from 'vue';
import { Link, router, useForm, usePage } from '@inertiajs/vue3';
import AppLayout from '../../Layouts/AppLayout.vue';
import { Banknote, CheckCircle2, CircleAlert, Copy, CreditCard, Plus, ReceiptText, Search, X } from '@lucide/vue';
type Team = { id: number; name: string };
type Invoice = { id: number; title: string; amount: number; discount: number; payable: number; paid: number; outstanding: number; due_date: string; status: string; payment_token: string; athlete: { id: number; name: string; membership_number: string }; team: string | null };
type Paginated = { data: Invoice[]; links: { url: string | null; label: string; active: boolean }[]; total: number; from: number; to: number };
type Payment = { id: number; athlete: string; title: string; amount: number; method: string; paid_at: string };
const props = defineProps<{ invoices: Paginated; teams: Team[]; filters: { search?: string; team?: string; status?: string }; summary: { charged: number; collected: number; outstanding: number; collection_rate: number; overdue_count: number; manual_collected: number; online_collected: number }; recentPayments: Payment[] }>();
const page = usePage();
const successMessage = computed(() => page.props.flash?.success as string | null);
const showIssue = ref(false); const payingInvoice = ref<Invoice | null>(null); const copiedInvoice = ref<number | null>(null);
const search = ref(props.filters.search || ''); const teamFilter = ref(props.filters.team || ''); const statusFilter = ref(props.filters.status || '');
const today = new Date().toISOString().slice(0, 16);
const iranToday = new Intl.DateTimeFormat('en-CA', { timeZone: 'Asia/Tehran', year: 'numeric', month: '2-digit', day: '2-digit' }).format(new Date());
const issueForm = useForm({ team_id: props.teams[0]?.id || null, title: 'شهریه ماهانه', amount: 1800000, due_date: iranToday });
const payForm = useForm({ amount: 0, method: 'card_transfer', reference_number: '', paid_at: today, notes: '' });
const money = (value: number) => new Intl.NumberFormat('fa-IR').format(value);
const dateLabel = (value: string) => new Intl.DateTimeFormat('fa-IR', { day: 'numeric', month: 'short' }).format(new Date(`${value}T12:00:00`));
const applyFilters = () => router.get('/finance', { search: search.value || undefined, team: teamFilter.value || undefined, status: statusFilter.value || undefined }, { preserveState: true, replace: true });
const issue = () => issueForm.post('/finance/issues', { preserveScroll: true, onSuccess: () => { showIssue.value = false; issueForm.reset(); } });
const openPayment = (invoice: Invoice) => { payingInvoice.value = invoice; payForm.amount = invoice.outstanding; payForm.method = 'card_transfer'; payForm.reference_number = ''; payForm.paid_at = today; payForm.notes = ''; payForm.clearErrors(); };
const submitPayment = () => { if (payingInvoice.value) payForm.post(`/finance/invoices/${payingInvoice.value.id}/payments`, { onSuccess: () => payingInvoice.value = null }); };
const copyLink = async (invoice: Invoice) => { await navigator.clipboard.writeText(`${window.location.origin}/pay/${invoice.payment_token}`); copiedInvoice.value = invoice.id; window.setTimeout(() => copiedInvoice.value = null, 1800); };
const statusLabel = (value: string) => ({ paid: 'تسویه‌شده', partial: 'پرداخت بخشی', unpaid: 'پرداخت‌نشده', overdue: 'سررسید گذشته' }[value] || value);
const statusClass = (value: string) => value === 'paid' ? 'tag-ok' : value === 'overdue' ? 'tag-danger' : 'tag-warn';
const methodLabel = (value: string) => ({ cash: 'نقدی', card_transfer: 'کارت‌به‌کارت', pos: 'کارتخوان', online: 'آنلاین' }[value] || value);
const paginationLabel = (label: string) => label.replace('&laquo; Previous', 'قبلی').replace('Next &raquo;', 'بعدی');
</script>
<template><AppLayout title="مالی و شهریه" eyebrow="وصول، بدهکاران و پرداخت" active="finance">
<div v-if="successMessage" class="mb-4 flex items-center gap-2 border border-[#bcd9ca] bg-[#edf7f1] px-4 py-3 text-[11px] font-bold text-[#236b54]"><CheckCircle2 :size="16" />{{ successMessage }}</div>
<section class="finance-summary mb-5"><div><p class="section-kicker">وصول ثبت‌شده</p><div class="mt-2 flex items-baseline gap-2"><strong class="text-3xl font-black">{{ money(summary.collected) }}</strong><span class="text-xs text-[#74818a]">تومان</span></div><p class="mt-3 text-[11px] text-[#6f7d87]">از مجموع {{ money(summary.charged) }} تومان صورتحساب</p></div><div class="finance-ring" :style="`--value:${summary.collection_rate}`"><div><strong>{{ summary.collection_rate }}٪</strong><span>وصول</span></div></div><button class="primary-sport-button" @click="showIssue = true"><Plus :size="17" /> صدور شهریه</button></section>
<section class="mb-5 grid border border-[#d9dfe1] bg-white sm:grid-cols-3"><div class="finance-metric"><CreditCard :size="19" /><div><span>دریافت آنلاین</span><strong>{{ money(summary.online_collected) }}</strong></div></div><div class="finance-metric border-y border-[#e2e5e6] sm:border-x sm:border-y-0"><Banknote :size="19" /><div><span>دریافت دستی</span><strong>{{ money(summary.manual_collected) }}</strong></div></div><div class="finance-metric"><CircleAlert :size="19" /><div><span>مانده کل · {{ summary.overdue_count }} معوق</span><strong class="text-[#c54f34]">{{ money(summary.outstanding) }}</strong></div></div></section>
<section class="grid gap-5 xl:grid-cols-[1.45fr_.55fr]"><article class="panel-flat overflow-hidden"><header class="users-toolbar"><form class="flex flex-1 flex-col gap-2 md:flex-row" @submit.prevent="applyFilters"><div class="relative min-w-0 flex-1"><Search class="absolute right-3 top-1/2 -translate-y-1/2 text-[#8a959b]" :size="15" /><input v-model="search" class="table-filter pr-9" placeholder="نام یا کد عضویت"></div><select v-model="teamFilter" class="table-filter md:max-w-40" @change="applyFilters"><option value="">همه تیم‌ها</option><option v-for="team in teams" :key="team.id" :value="team.id">{{ team.name }}</option></select><select v-model="statusFilter" class="table-filter md:max-w-40" @change="applyFilters"><option value="">همه وضعیت‌ها</option><option value="unpaid">پرداخت‌نشده</option><option value="partial">پرداخت بخشی</option><option value="paid">تسویه‌شده</option><option value="overdue">سررسید گذشته</option></select><button class="secondary-button justify-center">جست‌وجو</button></form></header>
<div class="overflow-x-auto"><table class="sport-table finance-table"><thead><tr><th>ورزشکار</th><th>صورتحساب</th><th>مبلغ / مانده</th><th>سررسید</th><th>وضعیت</th><th>عملیات</th></tr></thead><tbody><tr v-for="invoice in invoices.data" :key="invoice.id"><td><strong class="block">{{ invoice.athlete.name }}</strong><span class="mt-1 block text-[8px] text-[#8a959b]">{{ invoice.team }} · {{ invoice.athlete.membership_number }}</span></td><td>{{ invoice.title }}</td><td><strong class="block">{{ money(invoice.payable) }}</strong><span class="mt-1 block text-[8px] text-[#b14d37]">مانده: {{ money(invoice.outstanding) }}</span></td><td>{{ dateLabel(invoice.due_date) }}</td><td><span :class="statusClass(invoice.status)">{{ statusLabel(invoice.status) }}</span></td><td><div class="flex gap-1"><button v-if="invoice.outstanding" class="small-action" @click="openPayment(invoice)"><Banknote :size="13" /> دریافت</button><button v-if="invoice.outstanding" class="small-action" @click="copyLink(invoice)"><CheckCircle2 v-if="copiedInvoice === invoice.id" :size="13" /><Copy v-else :size="13" />{{ copiedInvoice === invoice.id ? 'کپی شد' : 'لینک' }}</button></div></td></tr><tr v-if="!invoices.data.length"><td colspan="6" class="py-12 text-center text-[#89949b]">صورتحسابی پیدا نشد.</td></tr></tbody></table></div>
<footer class="flex flex-col gap-3 border-t border-[#e2e5e6] px-5 py-4 sm:flex-row sm:items-center sm:justify-between"><p class="text-[9px] text-[#7d8990]">نمایش {{ invoices.from || 0 }} تا {{ invoices.to || 0 }} از {{ invoices.total }} صورتحساب</p><div class="flex gap-1"><Link v-for="link in invoices.links" :key="link.label" :href="link.url || '#'" class="pagination-link" :class="{ 'pagination-active': link.active, 'pointer-events-none opacity-40': !link.url }" v-html="paginationLabel(link.label)" /></div></footer></article>
<aside class="panel-flat"><header class="panel-head"><div><h3>آخرین دریافت‌ها</h3><p>تراکنش‌های موفق ثبت‌شده</p></div><ReceiptText :size="19" class="text-[#d2672c]" /></header><div class="divide-y divide-[#e6e8e8]"><Link v-for="payment in recentPayments" :key="payment.id" :href="`/finance/receipts/${payment.id}`" class="block p-4"><div class="flex items-center justify-between gap-2"><strong class="text-[10px]">{{ payment.athlete }}</strong><span class="text-[10px] font-black text-[#24745d]">{{ money(payment.amount) }}</span></div><div class="mt-2 flex justify-between text-[8px] text-[#879198]"><span>{{ payment.title }}</span><span>{{ methodLabel(payment.method) }}</span></div></Link></div></aside></section>
<div v-if="showIssue" class="modal-shell" @click.self="showIssue = false"><section class="modal-card"><header class="modal-head"><div><p class="section-kicker">صدور گروهی</p><h2>تعریف شهریه برای تیم</h2></div><button @click="showIssue = false"><X :size="20" /></button></header><form class="space-y-5 p-5" @submit.prevent="issue"><div class="grid gap-4 sm:grid-cols-2"><label class="form-label">تیم<select v-model="issueForm.team_id" class="form-input"><option v-for="team in teams" :key="team.id" :value="team.id">{{ team.name }}</option></select></label><label class="form-label">عنوان<input v-model="issueForm.title" class="form-input" placeholder="شهریه آبان"></label><label class="form-label">مبلغ هر ورزشکار (تومان)<input v-model="issueForm.amount" type="number" class="form-input" dir="ltr"><small v-if="issueForm.errors.amount">{{ issueForm.errors.amount }}</small></label><label class="form-label">تاریخ سررسید<input v-model="issueForm.due_date" type="date" class="form-input" dir="ltr"></label></div><div class="border-r-2 border-[#e87532] bg-white p-4 text-[9px] leading-6 text-[#687780]">برای تمام ورزشکاران فعال این تیم یک صورتحساب و لینک پرداخت مجزا ساخته می‌شود.</div><div class="flex justify-end gap-2"><button type="button" class="secondary-button" @click="showIssue = false">انصراف</button><button class="primary-sport-button" :disabled="issueForm.processing">صدور صورتحساب‌ها</button></div></form></section></div>
<div v-if="payingInvoice" class="modal-shell" @click.self="payingInvoice = null"><section class="modal-card"><header class="modal-head"><div><p class="section-kicker">ثبت دریافت دستی</p><h2>{{ payingInvoice.athlete.name }}</h2></div><button @click="payingInvoice = null"><X :size="20" /></button></header><form class="space-y-5 p-5" @submit.prevent="submitPayment"><div class="grid gap-4 sm:grid-cols-2"><label class="form-label">مبلغ دریافت (تومان)<input v-model="payForm.amount" type="number" :max="payingInvoice.outstanding" class="form-input" dir="ltr"><small v-if="payForm.errors.amount">{{ payForm.errors.amount }}</small></label><label class="form-label">روش پرداخت<select v-model="payForm.method" class="form-input"><option value="card_transfer">کارت‌به‌کارت</option><option value="cash">نقدی</option><option value="pos">کارتخوان</option></select></label><label class="form-label">شماره پیگیری<input v-model="payForm.reference_number" class="form-input" dir="ltr"></label><label class="form-label">زمان پرداخت<input v-model="payForm.paid_at" type="datetime-local" class="form-input" dir="ltr"></label></div><label class="form-label">توضیحات<textarea v-model="payForm.notes" class="form-textarea" rows="2"></textarea></label><div class="flex justify-end gap-2"><button type="button" class="secondary-button" @click="payingInvoice = null">انصراف</button><button class="primary-sport-button" :disabled="payForm.processing">ثبت و صدور رسید</button></div></form></section></div>
</AppLayout></template>
